    '#ifdef FSHIGHPRECISION\n    precision highp float;\n#else\n    precision mediump float;\n#endif\n#include \'ShaderUtils.glsl\';\n#include \'Lighting.glsl\';\n\nuniform vec3 u_CameraPos;\nuniform DirectionLight u_DirectionLight;\n\nuniform sampler2D u_MainTex;\nuniform sampler2D u_BumpMap;\nuniform sampler2D u_ORMMap;\nuniform sampler2D u_RampMap;\nuniform sampler2D u_MatCapTex;\nuniform float u_NormalScale;\nuniform float u_RampOffset;\nuniform float u_SpecMetalScale;\nuniform float u_SpecMetalScale2;\nuniform float u_CubeStrength;\nuniform float u_StylizedStrength;\nuniform float u_RimPower;\nuniform float u_RimSoftness;\nuniform float u_RimIntensity;\nuniform float u_RimLightEffect;\nuniform float u_LightStrength;\nuniform vec4 u_SpecDirection2;\nuniform vec4 u_BaseColor;\nuniform vec4 u_SpecMetalColor;\nuniform vec4 u_SpecMetalColor2;\nuniform vec4 u_RimColor;\nuniform vec4 u_OutlineColor;\n\nvarying vec2 v_Texcoord;\nvarying vec3 v_PositionWorld;\nvarying vec3 v_Normal;\nvarying vec3 v_Tangent;\nvarying vec3 v_biNormal;\nvarying mat4 v_View;\n\nvec3 ComputeF0(float specular, vec3 baseColor, float metallic){ \n    return lerp(vec3(specular * 0.08), baseColor, metallic); \n}\nfloat SmithJointGGXVisibilityTerm(float NdotL, float NdotV, float roughness){\n    float a = roughness;\n    float a2 = a * a;\n    float lambdaV = NdotL * sqrt((-NdotV * a2 + NdotV) * NdotV + a2);\n    float lambdaL = NdotV * sqrt((-NdotL * a2 + NdotL) * NdotL + a2);\n    return 0.5 / (lambdaV + lambdaL + 1e-5);\n}\nfloat GGXTerm(float NdotH, float roughness){\n    float a2 = roughness * roughness;\n    float d = (NdotH * a2 - NdotH) * NdotH + 1.0;\n    return 0.31830988618 * a2 / (d * d + 0.0000001);\n}\nvec3 FresnelTerm(vec3 c, float cosA){ return c + (1.0 - c) * pow(1.0 - cosA, 5.0); }\nfloat GetSpecularOcclusion(float metallic, float roughness, float occlusion){\n    return lerp(occlusion, 1.0, metallic * (1.0 - roughness) * (1.0 - roughness));\n}\nfloat ComputeEnvMapMipFromRoughness(float roughness){\n    float perceptualRoughness = roughness;\n    perceptualRoughness = perceptualRoughness * (1.7 - 0.7 * perceptualRoughness);\n    return perceptualRoughness * 6.0;\n}\nvec3 EnvBRDF(vec3 specColor, float roughness, float NdotV){\n    vec4 c0 = vec4(-1.0, -0.0275, -0.572, 0.022);\n    vec4 c1 = vec4(1.0, 0.0425, 1.04, -0.04);\n    vec4 r = roughness * c0 + c1;\n    float a004 = min(r.x * r.x, exp2(-9.28 * NdotV)) * r.x + r.y;\n    vec2 AB = vec2(-1.04, 1.04) * a004 + r.zw;\n    AB.y *= saturate(50.0 * specColor.g);\n    return specColor * AB.x + AB.y;\n}\n\nvoid main(){\n        // gl_FragColor = vec4(texture2D(u_RampMap, v_Texcoord).rgb, 1.0);\n    vec3 worldViewDir = normalize(u_CameraPos - v_PositionWorld);\n    worldViewDir.x *= -1.0;\n    vec3 worldLightDir = normalize(u_DirectionLight.Direction);\n    worldLightDir.yz *= -1.0;\n\n    vec3 worldLightDir2 = normalize(u_SpecDirection2.xyz);\n    // worldLightDir2.yz *= -1.0;\n\n    vec3 lightColor = u_DirectionLight.Color.rgb * u_LightStrength * 3.2;\n    mat3 TBN = mat3(normalize(v_Tangent), normalize(v_biNormal), normalize(v_Normal));\n    vec3 normalTangent = UnpackNormal(texture2D(u_BumpMap, v_Texcoord));\n    normalTangent.xy *= u_NormalScale;\n    normalTangent.z = sqrt(1.0 - saturate(dot(normalTangent.xy, normalTangent.xy)));\n    vec3 worldNormal = normalize(TBN * normalTangent);\n    vec3 worldHalfDir = normalize(worldViewDir + worldLightDir);\n    vec3 worldHalfDir2 = normalize(worldViewDir + worldLightDir2);\n    vec3 refDir = reflect(-worldViewDir, worldNormal);\n\n    vec3 albedo = texture2D(u_MainTex, v_Texcoord).rgb * u_BaseColor.rgb;\n    vec3 orm = texture2D(u_ORMMap, v_Texcoord).rgb;\n    orm = pow(orm, vec3(0.45));\n    float ao = orm.r;\n    float roughness = orm.g;\n    float metallic = orm.b;\n\n    vec3 diffColor = lerp(albedo, vec3(0.0), metallic).xyz;\n    vec3 specColor = ComputeF0(0.5, albedo.xyz, metallic);\n\n    float NoH = saturate(dot(worldNormal, worldHalfDir));   //有问题\n    // float VoH = saturate(dot(worldViewDir, worldHalfDir));\n    float NoV = saturate(dot(worldNormal, worldViewDir));\n    float NoL = saturate(dot(worldNormal, worldLightDir));  //有问题\n    float LoH = saturate(dot(worldLightDir, worldHalfDir));  //有问题\n    \n    float NoH2 = saturate(dot(worldNormal, worldHalfDir2));\n    float NoL2 = saturate(dot(worldNormal, worldLightDir2));\n    float LoH2 = saturate(dot(worldLightDir2, worldHalfDir2));\n\n    vec3 diffuseTerm = diffColor * 0.31830988618;\n\n    \n    float V = SmithJointGGXVisibilityTerm(NoL, NoV, roughness);\n    float D = GGXTerm(NoH, roughness * roughness);\n    vec3 F = FresnelTerm(specColor, LoH);\n    vec3 specularTerm = F * V * D;\n    specularTerm = clamp(specularTerm, 0.0, 10.0);\n\n    float V2 = SmithJointGGXVisibilityTerm(NoL2, NoV, roughness);\n    float D2 = GGXTerm(NoH2, roughness * roughness);\n    vec3 F2 = FresnelTerm(specColor, LoH2);\n    vec3 specularTerm2 = F2 * V2 * D2;\n    specularTerm2 = clamp(specularTerm2, 0.0, 10.0);\n\n#ifdef DEF_RampMap\n    float specRange = saturate(D * V);\n    vec4 specRampCol = texture2D(u_RampMap, vec2(specRange, 0.7));\n    specularTerm = F * clamp(specRampCol.rgb, 0.0, 10.0);\n\n    float specRange2 = saturate(D2 * V2);\n    vec4 specRampCol2 = texture2D(u_RampMap, vec2(specRange2, 0.7));\n    specularTerm2 = F * clamp(specRampCol2.rgb, 0.0, 10.0);\n\n    float x = max(0.0, NoL) + u_RampOffset;\n    vec2 UVramp = vec2(x, 0.3);\n    vec3 ShadowRamp1 = texture2D(u_RampMap, UVramp).rgb;\n    vec3 directLighting = 3.14159265359 * diffuseTerm * lightColor * ShadowRamp1;\n#else\n    vec3 directLighting = 3.14159265359 * diffuseTerm * lightColor * NoL;\n#endif\n\n    directLighting += 3.14159265359 * specularTerm * lightColor * NoL * u_SpecMetalColor.rgb * u_SpecMetalScale;\n\n    directLighting += 3.14159265359 * specularTerm2 * lightColor * NoL2 * u_SpecMetalColor2.rgb * u_SpecMetalScale2;\n    \n    vec3 viewNormal = normalize(v_View * vec4(worldNormal, 0.0)).xyz;\n    viewNormal.x *= -1.0;\n    vec2 uv = viewNormal.xy * 0.5 + 0.5;\n    uv.y = 1.0 - uv.y;\n    vec4 matcap = texture2D(u_MatCapTex, uv, 0.0);\n    \n#ifdef DEF_MatCapTex\n    vec3 indirectSpecular = matcap.rgb * EnvBRDF(specColor, roughness, NoV) * u_CubeStrength;\n#else\n    vec3 indirectSpecular = vec3(0.0);\n#endif\n\n    vec3 indirectLighting = indirectSpecular;\n\n    float ndotv = dot(normalize(worldNormal), worldViewDir);\n    float rim = 1.0 - saturate(ndotv);\n\n    float range = max(0.001, 1.0 - u_RimPower);\n    float softness = max(0.001, 1.0 - u_RimSoftness);\n    rim = smoothstep(range - softness, range + softness, rim);\n    vec3 rimColor = rim * u_RimColor.rgb * u_RimIntensity * 0.1;\n    vec3 finalColor = directLighting + indirectLighting + rimColor;\n\n#ifdef DEF_OutlineBounds\n    gl_FragColor = vec4(finalColor * u_OutlineColor.rgb, u_OutlineColor.a);\n#else\n    gl_FragColor = vec4(finalColor, 1.0);\n#endif\n}', 
