    'attribute vec4 position;\nattribute vec2 texcoord;\nuniform vec2 size;\n\n#ifdef WORLDMAT\nuniform mat4 mmat;\n#endif\nvarying vec2 v_texcoord;\nvoid main() {\n  #ifdef WORLDMAT\n  vec4 pos=mmat*position;\n  gl_Position =vec4((pos.x/size.x-0.5)*2.0,(0.5-pos.y/size.y)*2.0,pos.z,1.0);\n  #else\n  gl_Position =vec4((position.x/size.x-0.5)*2.0,(0.5-position.y/size.y)*2.0,position.z,1.0);\n  #endif\n  \n  v_texcoord = texcoord;\n}', 
    'attribute vec4 position;\nuniform vec2 size;\nuniform mat4 mmat;\nvoid main() {\n  vec4 pos=mmat*position;\n  gl_Position =vec4((pos.x/size.x-0.5)*2.0,(0.5-pos.y/size.y)*2.0,pos.z,1.0);\n}', 
    'precision mediump float;\n//precision highp float;\nvarying vec2 v_texcoord;\nuniform sampler2D u_texture;\nuniform sampler2D u_emo_texture;\nuniform half4 u_emo_anchor;\nuniform float alpha;\n#include?BLUR_FILTER  "parts/BlurFilter_ps_uniform.glsl";\n#include?COLOR_FILTER "parts/ColorFilter_ps_uniform.glsl";\n#include?GLOW_FILTER "parts/GlowFilter_ps_uniform.glsl";\n#include?COLOR_ADD "parts/ColorAdd_ps_uniform.glsl";\n\nvoid main() {\n    vec4 color= texture2D(u_texture, v_texcoord);\n    if (v_texcoord.x <= u_emo_anchor.x || v_texcoord.y <= u_emo_anchor.y || v_texcoord.x >= u_emo_anchor.z || v_texcoord.y >= u_emo_anchor.w)\n    {\n       \n    } else {\n        half w = u_emo_anchor.z - u_emo_anchor.x;\n        half h = u_emo_anchor.w - u_emo_anchor.y;\n        half2 emoTexcoord;\n        emoTexcoord.x = (u_texture.x - u_emo_anchor.x) / w;\n        emoTexcoord.y = (u_texture.y - u_emo_anchor.y) / h;\n        half4 emoColor = texture2D(_EmoTex, emoTexcoord);\n        color=lerp(color,emoColor* IN.color,step(color.a,emoColor.a));\n    }\n   color.a*=alpha;\n   color.rgb*=alpha;\n   gl_FragColor=color;\n   #include?COLOR_ADD "parts/ColorAdd_ps_logic.glsl";   \n   #include?BLUR_FILTER  "parts/BlurFilter_ps_logic.glsl";\n   #include?COLOR_FILTER "parts/ColorFilter_ps_logic.glsl";\n   #include?GLOW_FILTER "parts/GlowFilter_ps_logic.glsl";\n}', 
